package com.example.autojournal.shared.persistence

import jakarta.persistence.Id
import jakarta.persistence.MappedSuperclass
import jakarta.persistence.PostLoad
import jakarta.persistence.PostPersist
import jakarta.persistence.Transient
import org.springframework.data.domain.Persistable
import java.util.UUID

/**
 * Base for entities whose UUID primary key is generated by the application.
 * Implements [Persistable] so `save()` on a new entity issues a plain INSERT instead of a
 * SELECT followed by a merge (Spring Data otherwise treats a non-null ID as an existing row).
 */
@MappedSuperclass
abstract class AssignedIdEntity(
    @Id
    private val id: UUID = UUID.randomUUID(),
) : Persistable<UUID> {
    @Transient
    private var newEntity: Boolean = true

    override fun getId(): UUID = id

    override fun isNew(): Boolean = newEntity

    @PostPersist
    @PostLoad
    protected fun markNotNew() {
        newEntity = false
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other == null || other.javaClass != javaClass) return false
        return id == (other as AssignedIdEntity).id
    }

    override fun hashCode(): Int = id.hashCode()
}
